using System;
using System.Security.Cryptography;
using System.Text;

public class PkceHelper
{
    public static string GenerateCodeVerifier()
    {
        byte[] bytes = new byte[32];
        RandomNumberGenerator.Fill(bytes);
        return Base64UrlEncode(bytes);
    }

    public static string GenerateCodeChallenge(string codeVerifier)
    {
        byte[] verifierBytes = Encoding.UTF8.GetBytes(codeVerifier);
        byte[] hash = SHA256.HashData(verifierBytes);
        return Base64UrlEncode(hash);
    }

    public static bool Verify(string codeVerifier, string expectedChallenge)
    {
        var computedChallenge = GenerateCodeChallenge(codeVerifier);
        return computedChallenge == expectedChallenge;
    }

    public static string Base64UrlEncode(byte[] input)
    {
        return Convert.ToBase64String(input)
            .TrimEnd('=')
            .Replace('+', '-')
            .Replace('/', '_');
    }
}

public class Program
{
    public static void Main()
    {
        string verifier = PkceHelper.GenerateCodeVerifier();
        string challenge = PkceHelper.GenerateCodeChallenge(verifier);

        Console.WriteLine($"Code Verifier  : {verifier}");
        Console.WriteLine($"Code Challenge : {challenge}");

        bool isValid = PkceHelper.Verify(verifier, challenge);
        Console.WriteLine($"\nVerifikasi IdP Sukses: {isValid} (Harus True)");
    }
}

